import React from "react";

// картинки
import bear from "../../assets/games/bear.png";
import controller from "../../assets/games/controller.png";
import rocket from "../../assets/games/rocket.png";
import brain from "../../assets/games/brain.png";

const games = [
  {
    age: "Ages 2–5",
    title: "Little Explorers",
    image: bear,
    link: "https://www.educandy.com/", // пример
    color: "from-purple-200 to-purple-100",
  },
  {
    age: "Ages 6–8",
    title: "Play & Learn",
    image: controller,
    link: "https://www.coolmathgames.com/",
    color: "from-blue-200 to-blue-100",
  },
  {
    age: "Ages 9–12",
    title: "Smart Games",
    image: rocket,
    link: "https://www.mathplayground.com/",
    color: "from-green-200 to-green-100",
  },
  {
    age: "Ages 13–18",
    title: "Challenge Zone",
    image: brain,
    link: "https://www.chess.com/",
    color: "from-pink-200 to-pink-100",
  },
];

export default function Play() {
  return (
    <div className="p-6 md:p-10">
      <h1 className="text-3xl font-bold mb-8 text-center">
        Play & Learn 🎮
      </h1>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
        {games.map((game, index) => (
          <div
            key={index}
            className={`rounded-3xl p-6 bg-gradient-to-b ${game.color} shadow-lg flex flex-col items-center text-center`}
          >
            <img
              src={game.image}
              alt={game.title}
              className="w-40 h-40 object-contain mb-4"
            />

            <span className="text-sm font-semibold opacity-70">
              {game.age}
            </span>

            <h2 className="text-xl font-bold mt-1 mb-4">
              {game.title}
            </h2>

            <a
              href={game.link}
              target="_blank"
              rel="noreferrer"
              className="mt-auto px-6 py-2 rounded-full bg-white font-semibold shadow hover:scale-105 transition"
            >
              Play ▶
            </a>
          </div>
        ))}
      </div>
    </div>
  );
}
